# Databricks notebook source
# MAGIC %md
# MAGIC # 03 · Gold → SAP HANA Migration Cockpit staging tables
# MAGIC Writes each gold object into the staging table generated by the SAP S/4HANA Migration Cockpit
# MAGIC (approach *Migrate Data Using Staging Tables*). The SAP HANA JDBC driver (`com.sap.cloud.db.jdbc:ngdbc`)
# MAGIC is installed on the cluster; connectivity to HANA goes over private networking (VPN / ExpressRoute).
# MAGIC Each table is truncated first, so every mock load is repeatable. After this notebook the Migration
# MAGIC Cockpit transfer (prepare → map → simulate → migrate) is started in the Fiori app *Migrate Your Data*.

# COMMAND ----------
dbutils.widgets.text("object", "article")
dbutils.widgets.text("run_id", "")
obj, run_id = dbutils.widgets.get("object"), dbutils.widgets.get("run_id")
storage = spark.conf.get("spark.migration.storage_account")

import yaml
cfg = yaml.safe_load(open("/Workspace/Shared/migration/config/staging_tables.yaml"))
o = next(x for x in cfg["objects"] if x["name"] == obj)
if o["staging_table"].startswith("<"):
    raise ValueError(f"Staging table for {obj} not configured – create the migration project and enter the generated name")

secret = lambda k: dbutils.secrets.get("kv-migration", cfg["hana"][k])
url = f"jdbc:sap://{secret('host_secret')}:{secret('port_secret')}/?encrypt=true&validateCertificate=true"
props = {"user": secret("user_secret"), "password": secret("password_secret"), "driver": "com.sap.db.jdbc.Driver"}
schema, table = cfg["hana"]["schema"], o["staging_table"]
target = f'"{schema}"."{table}"'

# COMMAND ----------
gold = spark.read.format("delta").load(f"abfss://gold@{storage}.dfs.core.windows.net/{o['gold_path'].split('/')[-1]}")
gold = gold.drop(*[c for c in gold.columns if c.startswith("LEGACY_")])   # audit columns stay in the lake
(gold.write.format("jdbc").mode("overwrite")
     .option("url", url).option("dbtable", target).option("truncate", "true")   # TRUNCATE keeps the generated DDL
     .option("batchsize", 10000).options(**props).save())
rows = gold.count()
print(f"{rows} rows written to {target}")
dbutils.notebook.exit(str(rows))
